style.css:
@-moz-document domain("example.com"), url-prefix("http://"), url-prefix("https://") {
/* General Body Styling */
  body {
    background-color: #0d1117 !important; /* Very dark background */
    color: #00ff00 !important; /* Matrix green text */
    font-family: 'Consolas', 'Monaco', 'Lucida Console', monospace !important;
    line-height: 1.5 !important;
    overflow-x: hidden; /* Prevent horizontal scroll from background animation */

    /* Cascading Code Background */
    background-image:
      repeating-linear-gradient( /* Vertical lines, moving */
        to bottom,
        rgba(0, 255, 0, 0.05),
        rgba(0, 255, 0, 0.05) 1px,
        transparent 1px,
        transparent 20px /* Spacing of "code lines" */
      ),
      repeating-linear-gradient( /* Horizontal lines, static/slow */
        to right,
        rgba(0, 255, 0, 0.02),
        rgba(0, 255, 0, 0.02) 1px,
        transparent 1px,
        transparent 10px /* Spacing of "code columns" */
      );
    background-size: 100% 100px, 100px 100%; /* Size of repeating blocks */
    background-position: 0 0, 0 0; /* Initial positions */
    animation: matrix-scroll 60s linear infinite !important;
  }

  /* Matrix Scroll Animation */
  @keyframes matrix-scroll {
    from { background-position: 0 0, 0 0; }
    to { background-position: 0 10000px, 0 0; } /* Only the first layer (vertical lines) moves down */
  }

  /* Text Elements */
  h1, h2, h3, h4, h5, h6, p, span, a, li, label {
    color: #00ff00 !important;
    text-shadow: 0 0 2px rgba(0, 255, 0, 0.5); /* Subtle glow for all text */
    transition: all 0.3s ease !important;
  }

  /* Links */
  a {
    text-decoration: none !important;
  }
  a:hover {
    color: #33ff33 !important; /* Brighter green on hover */
    text-shadow: 0 0 5px #00ff00, 0 0 10px #00ff00, 0 0 15px #00ff00 !important; /* Stronger glow */
  }

  /* Input Fields, Textareas, Buttons */
  input[type="text"], input[type="password"], input[type="email"], input[type="number"],
  textarea, select, button, .btn, .button {
    background-color: #1a1a1a !important;
    border: 1px solid #006600 !important;
    padding: 5px 10px !important;
    border-radius: 3px !important;
    color: #00ff00 !important;
    transition: all 0.3s ease !important;
  }

  input[type="text"]:focus, input[type="password"]:focus, input[type="email"]:focus,
  textarea:focus, select:focus, button:focus, .btn:focus, .button:focus {
    outline: none !important;
    border-color: #00ff00 !important;
    box-shadow: 0 0 8px #00ff00, inset 0 0 8px rgba(0, 255, 0, 0.3) !important; /* Glowing border and inner glow */
  }

  button:hover, .btn:hover, .button:hover {
    background-color: #003300 !important;
    border-color: #00ff00 !important;
    box-shadow: 0 0 8px #00ff00, inset 0 0 8px rgba(0, 255, 0, 0.3) !important; /* Glowing border and inner glow */
    cursor: pointer !important;
  }

  /* Borders and elements that might have borders */
  div, section, article, header, footer, nav, aside, main, form, fieldset, legend,
  table, th, td, ul, ol, li, hr, figure, img, iframe, pre, code, blockquote,
  .card, .panel, .box, .container, .wrapper, [class*="border"], [id*="border"] {
    border-color: rgba(0, 100, 0, 0.5) !important; /* Subtle matrix green border */
    transition: all 0.3s ease !important;
  }

  /* Glowing Borders on Hover */
  div:hover, section:hover, article:hover, header:hover, footer:hover, nav:hover,
  aside:hover, main:hover, form:hover, fieldset:hover, legend:hover,
  table:hover, th:hover, td:hover, ul:hover, ol:hover, li:hover, figure:hover,
  img:hover, iframe:hover, pre:hover, code:hover, blockquote:hover,
  .card:hover, .panel:hover, .box:hover, .container:hover, .wrapper:hover,
  [class*="border"]:hover, [id*="border"]:hover {
    border-color: #00ff00 !important;
    box-shadow: 0 0 10px #00ff00, 0 0 20px rgba(0, 255, 0, 0.5) !important; /* Strong glow */
  }

  /* Signs (icons, specific text elements) */
  .icon, .symbol, [class*="icon"], [class*="symbol"],
  i, svg, [data-icon], [aria-label*="icon"], [role="img"] {
    transition: all 0.3s ease !important;
    filter: drop-shadow(0 0 2px rgba(0, 255, 0, 0.5)); /* Subtle glow for icons */
    color: #00ff00 !important; /* Ensure icons are green */
    fill: #00ff00 !important; /* For SVG fills */
  }

  .icon:hover, .symbol:hover, [class*="icon"]:hover, [class*="symbol"]:hover,
  i:hover, svg:hover, [data-icon]:hover, [aria-label*="icon"]:hover, [role="img"]:hover {
    filter: drop-shadow(0 0 5px #00ff00) drop-shadow(0 0 10px rgba(0, 255, 0, 0.5)) !important; /* Strong glow */
    color: #33ff33 !important;
    fill: #33ff33 !important;
    cursor: pointer !important;
  }

  /* Scrollbar Styling (Webkit - Chrome/Safari) */
  ::-webkit-scrollbar {
    width: 10px !important;
    height: 10px !important;
  }

  ::-webkit-scrollbar-track {
    background: #1a1a1a !important;
    border-radius: 5px !important;
  }

  ::-webkit-scrollbar-thumb {
    background: #006600 !important;
    border-radius: 5px !important;
    border: 1px solid #00ff00 !important;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: #00ff00 !important;
    box-shadow: 0 0 5px #00ff00 !important;
  }

  /* Selection styling */
  ::selection {
    background: rgba(0, 255, 0, 0.3) !important;
    color: #fff !important;
    text-shadow: none !important;
  }

  /* Override specific background colors that might persist */
  [style*="background-color"]:not(body), [style*="background"]:not(body) {
      background-color: transparent !important; /* Try to clear inline backgrounds */
      background-image: none !important;
  }
}
